code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    # Find patterned rows whose sequence is cut off by a trailing background run.
    candidates = []
    for r, row in enumerate(grid):
        if not any(v != background for v in row):
            continue
        tail = 0
        for v in reversed(row):
            if v != background:
                break
            tail += 1
        if tail:
            candidates.append((r, tail))
    if not candidates:
        return out

    # The shortest incomplete run identifies the continuation; equal rows form a band.
    shortest = min(tail for _, tail in candidates)
    targets = [r for r, tail in candidates if tail == shortest]
    first = targets[0]
    prefix = grid[first][:-shortest]

    # If the visible prefix is a clear short-period pattern, continue its marked cells;
    # otherwise the whole trailing gap is the continuation.
    period = None
    for p in range(1, min(5, len(prefix) // 2 + 1)):
        if all(prefix[i] == prefix[i % p] for i in range(len(prefix))):
            period = p
            break
    for r in targets:
        for c in range(w - shortest, w):
            predicted = grid[first][c % period] if period else None
            if period is None or predicted != background:
                out[r][c] = 1
    return out
'''
